import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Pista } from '../../pistas/entities/pista.entity';
import { Entrenador } from '../../entrenadores/entities/entrenador.entity';

@Injectable()
export class AsignarEntrenadorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Pista) private readonly pistas: Repository<Pista>,
    @InjectRepository(Entrenador) private readonly entrenadores: Repository<Entrenador>
  ) {}

  buscarPistaRepository(pistaId: number) {
    return this.pistas.findOneBy({ id: pistaId });
  }

  buscarEntrenadorRepository(entrenadorId: number) {
    return this.entrenadores.findOneBy({ id: entrenadorId });
  }

  async asignarEntrenadorRepository(pistaId: number, entrenadorId: number, rol: string) {
    const asignacion = { pistaId, entrenadorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarEntrenadorRepository } from './repository';

@Injectable()
export class AsignarEntrenadorService {
  constructor(private readonly repository: AsignarEntrenadorRepository) {}

  async asignarEntrenadorService(pistaId: number, entrenadorId: number, rol: string) {
    const pista = await this.repository.buscarPistaRepository(pistaId);
    const entrenador = await this.repository.buscarEntrenadorRepository(entrenadorId);
    if (!pista || !entrenador) {
      throw new NotFoundException('No existe la pista o el entrenador');
    }

    try {
      return await this.repository.asignarEntrenadorRepository(pistaId, entrenadorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El entrenador ya está asignado a esa pista');
      }
      throw error;
    }
  }
}

import { Body, Controller, Param, Post } from '@nestjs/common';
import { AsignarEntrenadorService } from './service';

@Controller('pistas/:pistaId/asignaciones')
export class AsignarEntrenadorController {
  constructor(private readonly service: AsignarEntrenadorService) {}

  @Post()
  asignar(@Param('pistaId') pistaId: string, @Body() datos: { entrenadorId: number; rol: string }) {
    return this.service.asignarEntrenadorService(Number(pistaId), datos.entrenadorId, datos.rol);
  }
}
